<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #080b13;
      --panel: #111827;
      --panel-strong: #172033;
      --text: #f8fafc;
      --muted: #cbd5e1;
      --accent: #8b5cf6;
      --accent-strong: #a78bfa;
      --success: #34d399;
      --border: #334155;
      --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(139, 92, 246, 0.3), transparent 34rem),
        radial-gradient(circle at bottom right, rgba(20, 184, 166, 0.22), transparent 30rem),
        var(--bg);
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 10;
      transform: translateY(-180%);
      border-radius: 999px;
      padding: 0.65rem 1rem;
      color: #09090b;
      background: #f8fafc;
      font-weight: 700;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--accent-strong);
      outline-offset: 3px;
    }

    main {
      width: min(100% - 2rem, 58rem);
      margin: 0 auto;
      padding: 4rem 0;
    }

    .quiz-card {
      overflow: hidden;
      border: 1px solid rgba(148, 163, 184, 0.25);
      border-radius: 1.5rem;
      background: rgba(15, 23, 42, 0.88);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .hero {
      padding: clamp(1.5rem, 4vw, 3rem);
      border-bottom: 1px solid rgba(148, 163, 184, 0.2);
      background: linear-gradient(135deg, rgba(139, 92, 246, 0.24), rgba(15, 23, 42, 0));
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(2rem, 6vw, 4rem);
      line-height: 1;
      letter-spacing: -0.05em;
    }

    .intro,
    .help-text,
    .result {
      color: var(--muted);
    }

    .intro {
      max-width: 44rem;
      margin: 0;
      font-size: 1.1rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
      padding: clamp(1rem, 4vw, 2rem);
    }

    .form-field {
      margin: 0;
      border: 1px solid var(--border);
      border-radius: 1.1rem;
      padding: clamp(1rem, 3vw, 1.5rem);
      background: linear-gradient(180deg, rgba(30, 41, 59, 0.78), rgba(15, 23, 42, 0.78));
    }

    .form-field fieldset {
      min-width: 0;
      margin: 0;
      border: 0;
      padding: 0;
    }

    legend {
      padding: 0 0.35rem;
      color: var(--text);
      font-size: 1.1rem;
      font-weight: 800;
    }

    .help-text {
      margin: 0.6rem 0 1rem;
    }

    .choices {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      min-height: 3rem;
      border: 1px solid rgba(148, 163, 184, 0.28);
      border-radius: 0.85rem;
      padding: 0.75rem;
      background: rgba(15, 23, 42, 0.72);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(167, 139, 250, 0.85);
      background: var(--panel-strong);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    input[type="checkbox"]:focus-visible,
    button:focus-visible {
      outline: 3px solid var(--accent-strong);
      outline-offset: 3px;
    }

    input[type="checkbox"]:checked + span {
      color: var(--text);
      font-weight: 700;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1rem;
      padding-top: 0.25rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.25rem;
      color: #ffffff;
      background: linear-gradient(135deg, var(--accent), #06b6d4);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 12px 28px rgba(139, 92, 246, 0.32);
    }

    button:hover {
      filter: brightness(1.08);
    }

    .result {
      min-height: 1.5rem;
      margin: 0;
      font-weight: 700;
    }

    .result:not(:empty) {
      color: var(--success);
    }

    @media (max-width: 35rem) {
      main {
        width: min(100% - 1rem, 58rem);
        padding: 0.5rem 0;
      }

      .quiz-card {
        border-radius: 1rem;
      }
    }

    @media (forced-colors: active) {
      .quiz-card,
      .form-field,
      .choice {
        border: 1px solid CanvasText;
      }

      button {
        border: 1px solid ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <main id="main-content">
    <section class="quiz-card" aria-labelledby="quiz-title">
      <div class="hero">
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p class="intro">Choose every answer that applies. Each question accepts more than one selection.</p>
      </div>

      <form id="quiz-form">
        <div class="form-field">
          <fieldset aria-describedby="question-1-help">
            <legend>1. Which of these are commonly used programming languages?</legend>
            <p class="help-text" id="question-1-help">Hint: Select languages used to write software, not markup-only technologies.</p>
            <div class="choices">
              <label class="choice" for="q1-python">
                <input id="q1-python" name="programming-languages" type="checkbox" value="Python">
                <span>Python</span>
              </label>
              <label class="choice" for="q1-html">
                <input id="q1-html" name="programming-languages" type="checkbox" value="HTML">
                <span>HTML</span>
              </label>
              <label class="choice" for="q1-rust">
                <input id="q1-rust" name="programming-languages" type="checkbox" value="Rust">
                <span>Rust</span>
              </label>
              <label class="choice" for="q1-java">
                <input id="q1-java" name="programming-languages" type="checkbox" value="Java">
                <span>Java</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>2. Which languages are often used for web development?</legend>
            <div class="choices">
              <label class="choice" for="q2-javascript">
                <input id="q2-javascript" name="web-languages" type="checkbox" value="JavaScript">
                <span>JavaScript</span>
              </label>
              <label class="choice" for="q2-php">
                <input id="q2-php" name="web-languages" type="checkbox" value="PHP">
                <span>PHP</span>
              </label>
              <label class="choice" for="q2-cobol">
                <input id="q2-cobol" name="web-languages" type="checkbox" value="COBOL">
                <span>COBOL</span>
              </label>
              <label class="choice" for="q2-typescript">
                <input id="q2-typescript" name="web-languages" type="checkbox" value="TypeScript">
                <span>TypeScript</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>3. Which languages are known for systems programming?</legend>
            <div class="choices">
              <label class="choice" for="q3-c">
                <input id="q3-c" name="systems-languages" type="checkbox" value="C">
                <span>C</span>
              </label>
              <label class="choice" for="q3-rust">
                <input id="q3-rust" name="systems-languages" type="checkbox" value="Rust">
                <span>Rust</span>
              </label>
              <label class="choice" for="q3-sql">
                <input id="q3-sql" name="systems-languages" type="checkbox" value="SQL">
                <span>SQL</span>
              </label>
              <label class="choice" for="q3-cpp">
                <input id="q3-cpp" name="systems-languages" type="checkbox" value="C++">
                <span>C++</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit quiz</button>
          <p class="result" id="quiz-result" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#quiz-form");
    const result = document.querySelector("#quiz-result");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = form.querySelectorAll("input[type='checkbox']:checked").length;
      const answerText = selectedCount === 1 ? "answer" : "answers";

      result.textContent = `Quiz submitted with ${selectedCount} selected ${answerText}.`;
    });
  </script>
</body>
</html>
