      padding: clamp(1.5rem, 4vw, 3rem);
      border-bottom: 1px solid rgba(148, 163, 184, 0.2);
      background: linear-gradient(135deg, rgba(139, 92, 246, 0.24), rgba(15, 23, 42, 0));
    }

    h1 {
      margin: 0 0 0.75rem;
      font-size: clamp(2rem, 6vw, 4rem);
      line-height: 1;
      letter-spacing: -0.05em;
    }

    .intro,
    .help-text,
    .result {
      color: var(--muted);
    }

    .intro {
      max-width: 44rem;
      margin: 0;
      font-size: 1.1rem;
    }

    form {
      display: grid;
      gap: 1.25rem;
      padding: clamp(1rem, 4vw, 2rem);
    }

    .form-field {
      margin: 0;
      border: 1px solid var(--border);
      border-radius: 1.1rem;
      padding: clamp(1rem, 3vw, 1.5rem);
      background: linear-gradient(180deg, rgba(30, 41, 59, 0.78), rgba(15, 23, 42, 0.78));
    }

    .form-field fieldset {
      min-width: 0;
      margin: 0;
      border: 0;
      padding: 0;
    }

    legend {
      padding: 0 0.35rem;
      color: var(--text);
      font-size: 1.1rem;
      font-weight: 800;
    }

    .help-text {
      margin: 0.6rem 0 1rem;
    }

    .choices {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .choice {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      min-height: 3rem;
      border: 1px solid rgba(148, 163, 184, 0.28);
      border-radius: 0.85rem;
      padding: 0.75rem;
      background: rgba(15, 23, 42, 0.72);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(167, 139, 250, 0.85);
      background: var(--panel-strong);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    input[type="checkbox"]:focus-visible,
    button:focus-visible {
      outline: 3px solid var(--accent-strong);
      outline-offset: 3px;
    }

    input[type="checkbox"]:checked + span {
      color: var(--text);
      font-weight: 700;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 1rem;
      padding-top: 0.25rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.9rem 1.25rem;
      color: #ffffff;
      background: linear-gradient(135deg, #7c3aed, #4f46e5);
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 12px 28px rgba(139, 92, 246, 0.32);
